query IssueQuery($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    issueOrPullRequest(number: $number) {
      __typename
      ... on Issue {
        id
        number
        title
        body
        state
        stateReason
        author {
          login
        }
        createdAt
        labels(first: 20) {
          totalCount
          nodes {
            name
            color
          }
        }
        assignees(first: 10) {
          totalCount
          nodes {
            login
          }
        }
        milestone {
          number
          title
        }
        comments(last: 100) {
          totalCount
          nodes {
            fullDatabaseId
            author {
              login
            }
            body
            createdAt
          }
        }
        repository {
          nameWithOwner
        }
        viewerCanClose
        viewerCanReopen
      }
      ... on PullRequest {
        number
      }
    }
  }
}
